const body = $input.item.json.body || $input.item.json;
const action = (body.action || 'APPROVE').toUpperCase();
const approvalId = body.approval_id || 'APP-301B1888';
const approver = body.approved_by || 'operations_supervisor_john';
const comments = body.comments || 'Mitigation authorized to avoid $255k customer stockout.';

if (action === 'APPROVE') {
  return {
    json: {
      status: 'APPROVED_AND_EXECUTED',
      approval_id: approvalId,
      decision: 'APPROVED',
      approved_by: approver,
      execution_details: {
        action_taken: 'BOOK_DEDICATED_EXPEDITE_DRAYAGE',
        carrier: 'Swift Priority Drayage',
        cost_authorized: '$1,250.00',
        time_saved_hours: 36.0,
        new_committed_eta: '2026-10-27T18:00:00Z',
        mitigation_state: 'ACTIVE_DISPATCH'
      },
      audit_log: {
        timestamp: new Date().toISOString(),
        comments: comments
      }
    }
  };
} else {
  return {
    json: {
      status: 'REJECTED_LOGGED',
      approval_id: approvalId,
      decision: 'REJECTED',
      approved_by: approver,
      message: 'Plan rejected. Case remanded to Manual Exception Review Queue.',
      audit_log: {
        timestamp: new Date().toISOString(),
        comments: comments
      }
    }
  };
}

const data = $input.item.json;
return {
  json: {
    dispatch_confirmation: {
      booking_id: 'BKG-EXPEDITE-' + Math.floor(100000 + Math.random() * 900000),
      approval_reference: data.approval_id,
      status: 'CARRIER_DISPATCH_CONFIRMED',
      carrier_instructions: 'Pickup container MSCU1234567 immediately upon terminal release at LA Pier 400. Dedicated team drive direct to Chicago DC.',
      authorized_by: data.approved_by
    }
  }
};
